from decimal import Decimal


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_or_zero(value: object) -> Decimal:
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account credit hold, enforcing legacy ACC-004 semantics."""
    updated_account = account.copy()

    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    credit_limit = _numeric_or_zero(account.get("CRED_LIMIT", ""))
    if credit_limit <= 0:
        raise BusinessRuleViolation(
            "E1004",
            "Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    audits = [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": str(account.get("ACCT_ID", "")),
        }
    ]
    return updated_account, audits
